// Slide 9: Abstract template base class for all buffer implementations
template<typename T>
class AbstractBuffer {
public:
    virtual void put(T item) = 0;
    virtual T get() = 0;
};

// Slide 10: Producer and consumer tasks sharing a buffer
static AbstractBuffer<ITEM> *buffer;

void producerTask() {
    ITEM item;
    while (true) {
        // produire item
        buffer->put(item);
    }
}

void consumerTask() {
    ITEM item;
    while (true) {
        item = buffer->get();
        // consommer item
    }
}

int main(void) {
    buffer = new Buffer1<ITEM>();
    PcoThread prod(producerTask);
    PcoThread cons(consumerTask);
    prod.join();
    cons.join();
    return 0;
}

template<typename T> class Buffer1a : public AbstractBuffer<T> {
public:
    Buffer1a() : waitEmpty(1) {
        // waitFull is default-initialized to 0
    }

    virtual ~Buffer1a() {}

    void put(T item) override {
        waitEmpty.acquire();
        element = item;
        waitFull.release();
    }

    T get() override {
        T item;
        waitFull.acquire();
        item = element;
        waitEmpty.release();
        return item;
    }

protected:
    T element;
    PcoSemaphore waitEmpty, waitFull;
};

#include <pcosynchro/pcosemaphore>

template<typename T> class BufferNa : public AbstractBuffer<T> {
protected:
    std::vector<T> elements;
    int writePointer;
    int readPointer;
    int bufferSize;
    PcoSemaphore waitNotFull, waitNotEmpty;

public:
    BufferNa(unsigned int size) : elements(size), writePointer(0),
        readPointer(0), bufferSize(size),
        waitNotFull(size), waitNotEmpty(0) {}

    virtual ~BufferNa() {}

    void put(T item) override {
        waitNotFull.acquire();
        elements[writePointer] = item;                 // RACE if N > 1 producers!
        writePointer = (writePointer + 1) % bufferSize; // RACE!
        waitNotEmpty.release();
    }

    T get() override {
        T item;
        waitNotEmpty.acquire();
        item = elements[readPointer];                   // RACE if M > 1 consumers!
        readPointer = (readPointer + 1) % bufferSize;   // RACE!
        waitNotFull.release();
        return item;
    }
};

#include <PcoSemaphore>

template<typename T> class BufferNa : public AbstractBuffer<T> {
protected:
    std::vector<T> elements;
    int writePointer;
    int readPointer;
    int bufferSize;
    PcoSemaphore mutex, waitNotFull, waitNotEmpty;

public:
    BufferNa(unsigned int size) : elements(size), writePointer(0),
        readPointer(0), bufferSize(size),
        mutex(1), waitNotFull(size), waitNotEmpty(0) {
    }

    virtual ~BufferNa() {}

    void put(T item) override {
        waitNotFull.acquire();
        mutex.acquire();
        elements[writePointer] = item;
        writePointer = (writePointer + 1) % bufferSize;
        waitNotEmpty.release();
        mutex.release();
    }

    T get() override {
        T item;
        waitNotEmpty.acquire();
        mutex.acquire();
        item = elements[readPointer];
        readPointer = (readPointer + 1) % bufferSize;
        waitNotFull.release();
        mutex.release();
        return item;
    }
};

#include <PcoSemaphore>

template<typename T> class BufferN : public AbstractBuffer<T> {
protected:
    std::vector<T> elements;
    int writePointer, readPointer, nbElements, bufferSize;
    PcoSemaphore mutex, waitProd, waitConso;
    unsigned nbWaitingProd, nbWaitingConso;

public:
    BufferN(unsigned int size) : elements(size), writePointer(0),
        readPointer(0), nbElements(0), bufferSize(size),
        mutex(1), waitProd(0), waitConso(0),
        nbWaitingProd(0), nbWaitingConso(0) {
    }

    virtual ~BufferN() {}

    void put(T item) override {
        mutex.acquire();
        if (nbElements == bufferSize) {
            nbWaitingProd += 1;
            mutex.release();
            waitProd.acquire(); // receives baton (mutex ownership)!
        }
        elements[writePointer] = item;
        writePointer = (writePointer + 1) % bufferSize;
        nbElements++;
        if (nbWaitingConso > 0) {
            nbWaitingConso -= 1;
            waitConso.release(); // passes baton to waiting consumer!
        } else {
            mutex.release();
        }
    }

    T get() override {
        T item;
        mutex.acquire();
        if (nbElements == 0) {
            nbWaitingConso += 1;
            mutex.release();
            waitConso.acquire(); // receives baton (mutex ownership)!
        }
        item = elements[readPointer];
        readPointer = (readPointer + 1) % bufferSize;
        nbElements--;
        if (nbWaitingProd > 0) {
            nbWaitingProd -= 1;
            waitProd.release(); // passes baton to waiting producer!
        } else {
            mutex.release();
        }
        return item;
    }
};

void put(T item) override {
    waitNotFull.acquire();
    mutex.acquire();
    elements[writePointer] = item;
    writePointer = (writePointer + 1) % bufferSize;
    mutex.release();          // Released BEFORE waitNotEmpty.release()
    waitNotEmpty.release();
}

T get() override {
    T item;
    waitNotEmpty.acquire();
    mutex.acquire();
    item = elements[readPointer];
    readPointer = (readPointer + 1) % bufferSize;
    mutex.release();          // Released BEFORE waitNotFull.release()
    waitNotFull.release();
    return item;
}
